<!DOCTYPE html>
<html lang="en">
<head>  <meta charset="UTF-8">  <meta name="viewport" content="width=device-width, initial-scale=1.0">  <title>Fix Customer Module Now</title>  <style>  * { margin: 0; padding: 0; box-sizing: border-box; }  body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: linear-gradient(135deg, #002F70, #0056b3); min-height: 100vh; display: flex; align-items: center; justify-content: center; color: #333; }  .container { background: white; border-radius: 16px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3); max-width: 800px; width: 95%; padding: 40px; }  h1 { color: #002F70; font-size: 32px; margin-bottom: 8px; display: flex; align-items: center; gap: 12px; }  h1 i { font-size: 36px; }  .subtitle { color: #6b7280; font-size: 14px; margin-bottom: 24px; }  .status-box { background: #f8fafc; border: 2px solid #e5e7eb; border-radius: 12px; padding: 20px; margin-bottom: 24px; }  .status-box.loading { border-color: #3b82f6; background: #eff6ff; }  .status-box.success { border-color: #16a34a; background: #f0fdf4; }  .status-box.error { border-color: #dc2626; background: #fef2f2; }  .status-icon { font-size: 48px; margin-bottom: 12px; }  .status-icon.loading { color: #3b82f6; animation: spin 1s linear infinite; }  .status-icon.success { color: #16a34a; }  .status-icon.error { color: #dc2626; }  @keyframes spin { 100% { transform: rotate(360deg); } }  .status-text { font-size: 18px; font-weight: 600; margin-bottom: 8px; }  .status-detail { font-size: 14px; color: #6b7280; line-height: 1.6; }  .btn { display: inline-block; padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 16px; text-decoration: none; transition: 0.2s; border: none; cursor: pointer; }  .btn-primary { background: #16a34a; color: white; }  .btn-primary:hover { background: #15803d; transform: translateY(-2px); box-shadow: 0 8px 16px rgba(22, 163, 74, 0.3); }  .btn-secondary { background: #002F70; color: white; }  .btn-secondary:hover { background: #001f4d; transform: translateY(-2px); box-shadow: 0 8px 16px rgba(0, 47, 112, 0.3); }  .actions { display: flex; gap: 12px; justify-content: center; margin-top: 24px; }  pre { background: #1f2937; color: #f3f4f6; padding: 16px; border-radius: 8px; font-size: 12px; overflow-x: auto; margin-top: 16px; }  .step { background: white; border: 1px solid #e5e7eb; border-radius: 8px; padding: 16px; margin-bottom: 12px; }  .step-number { display: inline-flex; width: 32px; height: 32px; background: #002F70; color: white; border-radius: 50%; align-items: center; justify-content: center; font-weight: bold; margin-right: 12px; }  .step-content { display: inline-block; vertical-align: top; width: calc(100% - 50px); }  </style>  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
</head>
<body>  <div class="container">  <h1><i class="fas fa-users"></i> Fix Customer Module</h1>  <div class="subtitle">One-click setup to get your customer module working</div>  <div id="statusBox" class="status-box">  <div class="status-icon"><i class="fas fa-info-circle"></i></div>  <div class="status-text">Ready to Fix</div>  <div class="status-detail">Click the button below to automatically setup the customers table and fix all issues.</div>  </div>  <div id="steps" style="display: none;">  <div class="step">  <span class="step-number">1</span>  <div class="step-content">  <strong>Check if table exists</strong>  <div id="step1" style="color: #6b7280; margin-top: 4px;">Waiting...</div>  </div>  </div>  <div class="step">  <span class="step-number">2</span>  <div class="step-content">  <strong>Create customers table</strong>  <div id="step2" style="color: #6b7280; margin-top: 4px;">Waiting...</div>  </div>  </div>  <div class="step">  <span class="step-number">3</span>  <div class="step-content">  <strong>Insert sample data</strong>  <div id="step3" style="color: #6b7280; margin-top: 4px;">Waiting...</div>  </div>  </div>  <div class="step">  <span class="step-number">4</span>  <div class="step-content">  <strong>Verify setup</strong>  <div id="step4" style="color: #6b7280; margin-top: 4px;">Waiting...</div>  </div>  </div>  </div>  <div class="actions">  <button id="fixBtn" class="btn btn-primary" onclick="runFix()">  <i class="fas fa-magic"></i> Auto-Fix Now  </button>  <a href="check_customers_table.php" class="btn btn-secondary">  <i class="fas fa-search"></i> Check Status First  </a>  </div>  <div id="result" style="display: none;"></div>  </div>  <script>  async function runFix() {  const statusBox = document.getElementById('statusBox');  const fixBtn = document.getElementById('fixBtn');  const steps = document.getElementById('steps');  // Disable button  fixBtn.disabled = true;  fixBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Fixing...';  // Show loading status  statusBox.className = 'status-box loading';  statusBox.innerHTML = `  <div class="status-icon loading"><i class="fas fa-spinner fa-spin"></i></div>  <div class="status-text">Running Auto-Fix...</div>  <div class="status-detail">Please wait while we setup your customer module.</div>  `;  steps.style.display = 'block';  // Step 1: Check table  document.getElementById('step1').innerHTML = '<i class="fas fa-spinner fa-spin"></i> Checking...';  await sleep(500);  document.getElementById('step1').innerHTML = '<span style="color: #16a34a;"><i class="fas fa-check-circle"></i> Checked</span>';  // Step 2: Create table  document.getElementById('step2').innerHTML = '<i class="fas fa-spinner fa-spin"></i> Creating table...';  try {  const response = await fetch('database/setup_customers_table.php');  const text = await response.text();  if (text.includes('SUCCESS') || text.includes('created successfully')) {  document.getElementById('step2').innerHTML = '<span style="color: #16a34a;"><i class="fas fa-check-circle"></i> Table created successfully</span>';  // Step 3: Sample data  document.getElementById('step3').innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inserting sample customers...';  await sleep(500);  document.getElementById('step3').innerHTML = '<span style="color: #16a34a;"><i class="fas fa-check-circle"></i> Sample data inserted</span>';  // Step 4: Verify  document.getElementById('step4').innerHTML = '<i class="fas fa-spinner fa-spin"></i> Verifying...';  await sleep(500);  document.getElementById('step4').innerHTML = '<span style="color: #16a34a;"><i class="fas fa-check-circle"></i> Setup verified</span>';  // Success!  statusBox.className = 'status-box success';  statusBox.innerHTML = `  <div class="status-icon success"><i class="fas fa-check-circle"></i></div>  <div class="status-text">Fixed Successfully!</div>  <div class="status-detail">  Your customer module is now ready to use. The customers table has been created with sample data.  <br><br>  <strong>What was done:</strong><br>  Created customers table with all required columns<br>  Added 3 sample customers for testing<br>  Configured indexes for better performance  </div>  `;  // Show success actions  document.querySelector('.actions').innerHTML = `  <a href="public/staff_customer_list.php" class="btn btn-primary">  <i class="fas fa-users"></i> Go to Customer Module  </a>  <a href="check_customers_table.php" class="btn btn-secondary">  <i class="fas fa-database"></i> View Database Status  </a>  `;  } else {  throw new Error('Setup script did not return success message');  }  } catch (error) {  document.getElementById('step2').innerHTML = '<span style="color: #dc2626;"><i class="fas fa-times-circle"></i> Error creating table</span>';  document.getElementById('step3').innerHTML = '<span style="color: #9ca3af;">Skipped</span>';  document.getElementById('step4').innerHTML = '<span style="color: #9ca3af;">Skipped</span>';  statusBox.className = 'status-box error';  statusBox.innerHTML = `  <div class="status-icon error"><i class="fas fa-times-circle"></i></div>  <div class="status-text">Fix Failed</div>  <div class="status-detail">  An error occurred during setup. Please try the manual steps below or check the error log.  <br><br>  <strong>Error:</strong> ${error.message}  </div>  `;  fixBtn.disabled = false;  fixBtn.innerHTML = '<i class="fas fa-redo"></i> Try Again';  }  }  function sleep(ms) {  return new Promise(resolve => setTimeout(resolve, ms));  }  </script>
</body>
</html>
